и наличии циклов.", "Каждый id в списках dependencies, changed и cached должен быть ключом dependencies; иначе ValueError. Проверять неизвестные ссылки даже в незатронутых компонентах и при пустом cached или changed."], "examples": [{"id": "V01", "input": {"dependencies": {}, "changed": [], "cached": []}, "expected": {"invalidated": [], "remaining": []}}, {"id": "V02", "input": {"dependencies": {"source": [], "report": ["source"]}, "changed": ["source"], "cached": ["source", "report"]}, "expected": {"invalidated": ["report", "source"], "remaining": []}}, {"id": "V03", "input": {"dependencies": {"source": [], "report": ["source"]}, "changed": ["report"], "cached": ["source", "report"]}, "expected": {"invalidated": ["report"], "remaining": ["source"]}}]}, "visible_cases": [{"id": "V01", "input": {"dependencies": {}, "changed": [], "cached": []}, "expected": {"invalidated": [], "remaining": []}}, {"id": "V02", "input": {"dependencies": {"source": [], "report": ["source"]}, "changed": ["source"], "cached": ["source", "report"]}, "expected": {"invalidated": ["report", "source"], "remaining": []}}, {"id": "V03", "input": {"dependencies": {"source": [], "report": ["source"]}, "changed": ["report"], "cached": ["source", "report"]}, "expected": {"invalidated": ["report"], "remaining": ["source"]}}, {"id": "V04", "input": {"dependencies": {"a": [], "b": ["a"], "c": ["b"], "z": []}, "changed": ["a"], "cached": ["c", "z"]}, "expected": {"invalidated": ["c"], "remaining": ["z"]}}, {"id": "V05", "input": {"dependencies": {"a": ["b"], "b": ["a"], "z": []}, "changed": ["a"], "cached": ["a", "b", "z"]}, "expected": {"invalidated": ["a", "b"], "remaining": ["z"]}}, {"id": "V06", "input": {"dependencies": {"a": ["missing"]}, "changed": [], "cached": ["a"]}, "raises": "ValueError"}], "code": "def solve(data):
    dependencies = data['dependencies']
    nodes = set(dependencies)
    for requirements in dependencies.values():
        for requirement in requirements:
            if requirement not in nodes:
                raise ValueError('dependency')
    for node in data['changed'] + data['cached']:
        if node not in nodes:
            raise ValueError('node')
    affected = set(data['changed'])
    pending = list(data['changed'])
    while pending:
        node = pending.pop()
        for requirement in dependencies[node]:
            if requirement not in affected:
                affected.add(requirement)
                pending.append(requirement)
    cached = set(data['cached'])
    return {'invalidated': sorted(cached.intersection(affected)),
            'remaining': sorted(cached.difference(affected))}
", "code_sha256": "4058fe3e9e17d5ab0f1724f7bc620dd7b90a10f6458bec5347bee6d0c167b757", "last_test_report": null, "tokens_used": 0, "token_limit": 60000}

